CREATE TABLE IF NOT EXISTS legal_wiki.normalized_payloads (payload_id bigint PRIMARY KEY REFERENCES legal_wiki.raw_ingestion_payloads(id),kind text NOT NULL CHECK(kind IN ('statute','precedent')),normalized_json jsonb NOT NULL,content_sha256 text NOT NULL CHECK(length(content_sha256)=64),created_at timestamptz NOT NULL DEFAULT now(),CHECK(normalized_json->>'verified'='false' AND normalized_json->>'kind'=kind AND normalized_json->>'content_sha256'=content_sha256));
